package com.adproject.resume.api;
import com.adproject.common.security.AuthenticatedUser; import com.adproject.resume.application.CandidateResumeService; import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/candidate/resume") public class CandidateResumeController {private final CandidateResumeService service;public CandidateResumeController(CandidateResumeService service){this.service=service;}@GetMapping ResumeDtos.ResumeResponse get(@AuthenticationPrincipal AuthenticatedUser u){return service.get(u);}@PutMapping ResumeDtos.ResumeResponse put(@AuthenticationPrincipal AuthenticatedUser u,@Valid @RequestBody ResumeDtos.SaveResumeRequest r){return service.save(u,r);}}
